HTML='<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f6f8fb"><meta name="apple-mobile-web-app-capable" content="yes"><title>Tairon Offerte · Sconti, prezzi e occasioni in tempo reale</title><link rel="icon" type="image/png" sizes="192x192" href="/icon-192.png"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png"><link rel="manifest" href="/manifest.webmanifest"><link rel="manifest" href="/manifest.webmanifest"><meta name="apple-mobile-web-app-title" content="Tairon Offerte"><meta name="application-name" content="Tairon Offerte"><style>\n:root{--bg:#f5f7fb;--card:#fff;--ink:#111827;--muted:#7b8797;--line:#e5eaf0;--red:#ff3b4e;--green:#12b76a;--ice:#dff8ff;--blue:#1677ff;--shadow:0 8px 24px rgba(20,35,55,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display",Arial,sans-serif;color:var(--ink);padding-bottom:94px}.app{max-width:760px;margin:auto;padding:calc(env(safe-area-inset-top) + 14px) 14px 26px}button,input,select{font:inherit}.top{display:flex;align-items:center;justify-content:space-between;gap:10px}.brand{display:flex;align-items:center;gap:10px}.logo{width:48px;height:48px;border-radius:15px;overflow:hidden;box-shadow:0 6px 16px rgba(255,59,78,.18);flex:0 0 auto}.logo img{width:100%;height:100%;object-fit:cover;display:block}.brand h1{font-size:22px;margin:0}.brand small{color:var(--muted)}.status{display:flex;align-items:center;gap:6px;padding:8px 10px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:11px;font-weight:800}.dot{width:8px;height:8px;border-radius:50%;background:#b8c2ce}.status.online .dot{background:var(--green)}.status.offline .dot{background:var(--red)}\n.toolbar{display:grid;grid-template-columns:1fr auto;gap:8px;margin:14px 0}.search{display:flex;align-items:center;background:#fff;border:1px solid var(--line);border-radius:16px;padding:11px 12px}.search input{border:0;outline:0;width:100%;background:transparent}.scan{border:0;background:#111827;color:#fff;border-radius:16px;padding:0 14px;font-weight:800}.filters{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}.field{background:#fff;border:1px solid var(--line);border-radius:15px;padding:9px 10px}.field label{display:block;color:var(--muted);font-size:9px;margin-bottom:4px}.field select{border:0;background:transparent;width:100%;font-weight:800;outline:0}.hero{background:linear-gradient(135deg,#e8fbff,#fff 68%);border:1px solid #d9edf2;border-radius:24px;padding:16px;box-shadow:var(--shadow);margin:10px 0 14px}.hero h2{font-size:24px;letter-spacing:-.04em;margin:0 0 6px}.hero p{font-size:12px;color:#66768a;line-height:1.45;margin:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:13px}.stat{background:rgba(255,255,255,.9);border:1px solid #e8eff3;border-radius:14px;padding:10px}.stat b{display:block;font-size:18px}.stat span{font-size:9px;color:var(--muted)}\n.section{display:flex;justify-content:space-between;align-items:center;margin:17px 2px 9px}.section h3{margin:0;font-size:18px}.section small{color:var(--muted)}.grid{display:grid;gap:9px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:12px;box-shadow:0 3px 12px rgba(20,35,55,.04)}.row{display:flex;justify-content:space-between;gap:10px}.source{font-size:9px;font-weight:900;padding:5px 7px;border-radius:999px}.source.online{background:#eaf2ff;color:#135fb7}.source.market{background:#e9faf0;color:#0c844a}.score{font-size:10px;color:#67768a;font-weight:800}.card h4{font-size:15px;margin:8px 0 4px}.meta{font-size:10px;color:var(--muted)}.priceRow{display:flex;align-items:end;gap:7px;margin-top:9px;flex-wrap:wrap}.price{font-size:23px;font-weight:900}.old{text-decoration:line-through;color:#9aa6b5;font-size:10px;margin-bottom:4px}.drop{color:var(--green);font-size:10px;font-weight:900;margin-bottom:4px}.badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.badge{padding:5px 7px;border-radius:999px;font-size:9px;font-weight:900}.badge.red{background:#fff0f2;color:#d53b49}.badge.green{background:#eafaf0;color:#0d854b}.badge.ice{background:var(--ice);color:#236b79}.open{margin-top:9px;border:0;background:#f1f4f7;border-radius:11px;padding:8px 10px;font-size:10px;font-weight:900}.alerts{display:grid;gap:8px}.alert{background:#fff;border:1px solid var(--line);border-left:4px solid var(--red);border-radius:15px;padding:10px}.alert.market{border-left-color:var(--green)}.alert b{font-size:11px}.alert p{font-size:10px;color:#596a7f;margin:5px 0 0}.settings{background:#fff;border:1px solid var(--line);border-radius:20px;padding:13px;margin-bottom:10px}.settings h4{margin:0 0 9px}.settingsGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.settings input,.settings select{width:100%;border:0;background:transparent;outline:0;font-weight:800}.save{width:100%;margin-top:9px;border:0;background:#111827;color:#fff;border-radius:13px;padding:10px;font-weight:900}.watchForm{display:grid;grid-template-columns:1.5fr .8fr;gap:8px}.watchList{display:grid;gap:7px;margin-top:9px}.rule{display:flex;justify-content:space-between;gap:8px;align-items:center;border:1px solid var(--line);border-radius:13px;padding:9px}.rule b{font-size:11px}.rule span{display:block;font-size:9px;color:var(--muted)}.del{border:0;background:#fff0f2;color:#d33d49;border-radius:9px;padding:7px;font-size:9px;font-weight:900}.empty{background:#fff;border:1px dashed #d5dde6;border-radius:18px;padding:24px;text-align:center;color:var(--muted);font-size:12px}.nav{position:fixed;bottom:0;left:0;right:0;background:rgba(255,255,255,.95);border-top:1px solid var(--line);padding:8px 10px calc(8px + env(safe-area-inset-bottom));backdrop-filter:blur(18px)}.navin{max-width:760px;margin:auto;display:grid;grid-template-columns:repeat(3,1fr)}.nav button{border:0;background:transparent;color:#8d9aac;padding:8px;border-radius:12px;font-size:10px}.nav button.active{color:#111827;background:#f1f4f7}@media(min-width:680px){.grid{grid-template-columns:1fr 1fr}}\n</style></head><body><div class="app">\n<div class="top"><div class="brand"><div class="logo"><img src="data:image/png;base64," alt="Tairon Offerte"></div><div><h1>Tairon Offerte</h1><small>Sconti, prezzi e occasioni in tempo reale · <span id="appVersion">caricamento…</span></small></div></div><div id="status" class="status"><span class="dot"></span><span id="statusText">Connessione…</span></div></div>\n<div class="toolbar"><div class="search"><input id="q" placeholder="Cerca prodotto, marca o negozio"></div><button id="scanBtn" class="scan">Scansiona</button></div>\n<div class="filters"><div class="field"><label>Regione</label><select id="region"><option>Lombardia</option><option>Veneto</option><option>Campania</option><option>Emilia-Romagna</option></select></div><div class="field"><label>Fonte</label><select id="source"><option value="all">Tutte</option><option value="online">Online</option><option value="market">Supermercati</option></select></div></div>\n<section class="hero"><h2>Offerte in tempo reale.</h2><p>Tairon Offerte legge i dati direttamente dal suo motore prezzi. Quando lo scanner trova un nuovo prezzo, il database e gli alert si aggiornano automaticamente.</p><div class="stats"><div class="stat"><b id="dealCount">0</b><span>offerte reali dal backend</span></div><div class="stat"><b id="alertCount">0</b><span>alert generati</span></div><div class="stat"><b id="productCount">0</b><span>prodotti monitorati</span></div></div></section>\n<div id="dealsView"><div class="section"><h3>Super offerte supermercati</h3><small>Esselunga · LIVE</small></div><div id="marketOffers" class="grid"></div><div class="section"><h3>Volantini</h3><small>approfondimento</small></div><div id="marketPromos" class="grid"></div><div class="section"><h3>Offerte online rilevate</h3><small id="updated">—</small></div><main id="deals" class="grid"></main></div>\n<div id="alertsView" hidden><div class="section"><h3>Centro Alert</h3><small>server</small></div><div class="settings"><h4>Radar automatico</h4><div class="settingsGrid"><div class="field"><label>Sconto minimo %</label><input id="minDiscount" type="number" min="5" max="95"></div><div class="field"><label>Deal Score minimo</label><input id="minScore" type="number" min="50" max="100"></div><div class="field"><label>Scansione ogni secondi</label><input id="scanSeconds" type="number" min="10" max="3600"></div><div class="field"><label>Fonte</label><select id="settingSource"><option value="all">Tutte</option><option value="online">Online</option><option value="market">Supermercati</option></select></div></div><button id="saveSettings" class="save">Salva impostazioni server</button></div><div class="settings"><h4>Watchlist</h4><div class="watchForm"><div class="field"><label>Prodotto / marca</label><input id="watchQuery" placeholder="es. Rummo"></div><div class="field"><label>Sotto €</label><input id="watchPrice" type="number" step="0.01" placeholder="1.00"></div></div><div class="field" style="margin-top:8px"><label>Fonte</label><select id="watchSource"><option value="all">Tutte</option><option value="online">Online</option><option value="market">Supermercati</option></select></div><button id="addWatch" class="save">Aggiungi alert</button><div id="watchList" class="watchList"></div></div><div class="section"><h3>Alert rilevati</h3><small id="alertUpdated">—</small></div><div id="alerts" class="alerts"></div></div>\n<div id="systemView" hidden><div class="section"><h3>Stato sistema</h3><small>diagnostica</small></div><div id="systemBox" class="settings"></div></div>\n</div><nav class="nav"><div class="navin"><button class="active" data-view="deals">⚡<br>Offerte</button><button data-view="alerts">🔔<br>Alert</button><button data-view="system">●<br>Sistema</button></div></nav>\n<script>\nconst $=s=>document.querySelector(s), money=v=>new Intl.NumberFormat(\'it-IT\',{style:\'currency\',currency:\'EUR\'}).format(Number(v||0));\nlet health=null,deals=[],alerts=[],settings=null,watch=[],sources=null,promotions=[],marketOffers=[];\nasync function api(path,opts={}){const r=await fetch(path,{headers:{\'Content-Type\':\'application/json\'},...opts});if(!r.ok)throw new Error(`${r.status} ${path}`);return r.json()}\nfunction setStatus(ok){$(\'#status\').className=\'status \'+(ok?\'online\':\'offline\');$(\'#statusText\').textContent=ok?\'Backend online\':\'Backend offline\'}\nfunction dealCard(d){const market=d.source_type===\'market\';const original=d.original_price||d.avg||d.price;const rawDrop=d.discount_pct??Math.max(0,(1-d.price/original)*100);return `<article class="card"><div class="row"><span class="source ${market?\'market\':\'online\'}">${market?\'SUPERMERCATO\':\'ONLINE\'} · ${d.retailer}</span><span class="score">${d.id?.startsWith(\'amazon-\')?\'LIVE · \':\'\'}Score ${d.score}/100</span></div><h4>${d.title}</h4><div class="meta">${d.brand||\'\'}${market&&d.region?\' · \'+d.region:\'\'}${d.unit?\' · \'+d.unit:\'\'}</div><div class="priceRow"><div class="price">${money(d.price)}</div><div class="old">${money(original)}</div><div class="drop">-${Math.round(rawDrop)}%</div></div><div class="badges"><span class="badge ice">media ${money(d.avg)}</span><span class="badge green">min ${money(d.min)}</span>${d.score>=85?\'<span class="badge red">ALERT</span>\':\'\'}</div>${d.url?`<button class="open" onclick="window.open(\'${d.url}\',\'_blank\')">Apri negozio</button>`:\'\'}</article>`}\nfunction renderMarketOffers(){const box=$("#marketOffers");if(!box)return;const arr=marketOffers||[];box.innerHTML=arr.length?arr.slice(0,24).map(p=>`<article class="card"><div class="row"><span class="source market">${p.retailer}</span><span class="badge red">-${Math.round(p.discount_pct||0)}%</span></div><h4>${p.title}</h4><div class="priceRow"><div class="price">${money(p.price)}</div>${p.original_price?`<div class="old">${money(p.original_price)}</div>`:""}</div><div class="meta">${p.validity||""}</div>${p.url?`<a class="open" href="${p.url}" target="_blank" style="display:inline-block;text-decoration:none">Sfoglia volantino</a>`:""}</article>`).join(""):`<div class="empty">Nessuna singola offerta scontata estratta al momento.</div>`;}\nfunction renderPromotions(){const box=$("#marketPromos");if(!box)return;const arr=promotions||[];box.innerHTML=arr.length?arr.slice(0,4).map(p=>`<article class="card"><div class="row"><span class="source market">${p.retailer}</span><span class="score">VOLANTINO</span></div><h4>${p.title}</h4><div class="meta">${p.validity||""}</div>${(p.pdf_url||p.url)?`<a class="open" href="${p.pdf_url||p.url}" target="_blank" style="display:inline-block;text-decoration:none">Sfoglia volantino</a>`:""}</article>`).join(""):`<div class="empty">Nessun volantino disponibile per questa regione.</div>`;}\nfunction renderDeals(){const q=$(\'#q\').value.trim().toLowerCase();const arr=deals.filter(d=>!q||(`${d.title} ${d.brand||\'\'} ${d.retailer}`).toLowerCase().includes(q));$(\'#deals\').innerHTML=arr.length?arr.map(dealCard).join(\'\'):\'<div class="empty">Nessuna offerta con questi filtri.</div>\';$(\'#dealCount\').textContent=arr.length;$(\'#updated\').textContent=\'Aggiornato ora\'}\nfunction renderAlerts(){ $(\'#alerts\').innerHTML=alerts.length?alerts.map(a=>`<div class="alert ${a.product_id.includes(\'esselunga\')||a.product_id.includes(\'coop\')||a.product_id.includes(\'conad\')||a.product_id.includes(\'despar\')?\'market\':\'\'}"><b>${a.kind===\'watchlist\'?\'🎯\':\'🔥\'} ${a.title}</b><p>${a.message}</p></div>`).join(\'\'):\'<div class="empty">Nessun alert ancora.</div>\';$(\'#alertCount\').textContent=alerts.length;$(\'#alertUpdated\').textContent=\'Aggiornato ora\';$(\'#watchList\').innerHTML=watch.length?watch.map(r=>`<div class="rule"><div><b>${r.query}</b><span>${r.source_type} · sotto ${r.max_price?money(r.max_price):\'qualsiasi prezzo\'}${r.region?\' · \'+r.region:\'\'}</span></div><button class="del" onclick="deleteWatch(${r.id})">Rimuovi</button></div>`).join(\'\'):\'<div class="empty" style="padding:15px">Nessuna watchlist.</div>\'}\nfunction renderSystem(){if(!health){$(\'#systemBox\').innerHTML=\'<b>Backend non raggiungibile</b>\';return}const am=sources?.sources?.amazon;$(\'#systemBox\').innerHTML=`<h4 style="margin-top:0">Backend Tairon Offerte ${health.version}</h4><p style="font-size:12px;color:#66768a">Prodotti: <b>${health.products}</b><br>Alert eventi: <b>${health.events}</b><br>Ultimo controllo: <b>${new Date(health.time).toLocaleString(\'it-IT\')}</b></p><p style="font-size:11px;color:#7b8797">Scanner automatico: ${settings?.auto_enabled?\'attivo\':\'disattivo\'} · ogni ${settings?.scan_seconds||\'?\'} s · regione ${settings?.region||\'?\'}</p><hr style="border:0;border-top:1px solid #e5eaf0;margin:12px 0"><b style="font-size:12px">Fonti dati</b><p style="font-size:11px;line-height:1.8;color:#66768a">Amazon Creators API: <b>${am?.live?\'🟢 LIVE\':(sources?.amazon_configured?\'🟠 errore\':\'⚪ da configurare\')}</b>${am?.items?\' · \'+am.items+\' prodotti\':\'\'}<br>Demo: <b>${sources?.demo_mode?\'attivi\':\'disattivati\'}</b><br>Supermercati / Esselunga: <b>${sources?.sources?.supermarkets?.live?\'🟢 LIVE\':\'🟠 non raggiungibile\'}</b>${sources?.sources?.supermarkets?.items?\' · \'+sources.sources.supermarkets.items+\' promozioni\':\'\'}</p>`}\nasync function loadAll(){try{health=await api(\'/api/health\');setStatus(true);const av=$(\'#appVersion\');if(av)av.textContent=health.version;const region=$(\'#region\').value,source=$(\'#source\').value;[deals,alerts,settings,watch,sources,promotions]=await Promise.all([api(`/api/deals?region=${encodeURIComponent(region)}&source=${source}`),api(\'/api/alerts?limit=50\'),api(\'/api/settings\'),api(\'/api/watchlist\'),api(\'/api/sources\'),api(`/api/promotions?region=${encodeURIComponent(region)}`)]);$(\'#productCount\').textContent=health.products;$(\'#minDiscount\').value=settings.min_discount;$(\'#minScore\').value=settings.min_score;$(\'#scanSeconds\').value=settings.scan_seconds;$(\'#settingSource\').value=settings.source_filter;renderMarketOffers();renderPromotions();renderDeals();renderAlerts();renderSystem()}catch(e){console.error(e);setStatus(false);$(\'#deals\').innerHTML=\'<div class="empty">Avvia il backend Tairon Offerte per vedere i dati live.</div>\'}}\nasync function scan(){const b=$(\'#scanBtn\');b.disabled=true;b.textContent=\'Scansione…\';try{await api(\'/api/scan/now\',{method:\'POST\'});await loadAll()}finally{b.disabled=false;b.textContent=\'Scansiona\'}}\nasync function saveSettings(){const body={auto_enabled:true,min_discount:+$(\'#minDiscount\').value,min_score:+$(\'#minScore\').value,scan_seconds:+$(\'#scanSeconds\').value,source_filter:$(\'#settingSource\').value,region:$(\'#region\').value};await api(\'/api/settings\',{method:\'PUT\',body:JSON.stringify(body)});await loadAll()}\nasync function addWatch(){const q=$(\'#watchQuery\').value.trim(),price=+$(\'#watchPrice\').value;if(!q||!price)return alert(\'Inserisci prodotto e prezzo target\');await api(\'/api/watchlist\',{method:\'POST\',body:JSON.stringify({query:q,max_price:price,source_type:$(\'#watchSource\').value,region:$(\'#watchSource\').value===\'market\'?$(\'#region\').value:null,enabled:true})});$(\'#watchQuery\').value=\'\';$(\'#watchPrice\').value=\'\';await loadAll()}\nasync function deleteWatch(id){await api(\'/api/watchlist/\'+id,{method:\'DELETE\'});await loadAll()}\n$(\'#scanBtn\').onclick=scan;$(\'#q\').oninput=renderDeals;$(\'#region\').onchange=async()=>{if(settings){settings.region=$(\'#region\').value}await loadAll()};$(\'#source\').onchange=loadAll;$(\'#saveSettings\').onclick=saveSettings;$(\'#addWatch\').onclick=addWatch;document.querySelectorAll(\'.nav button\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'.nav button\').forEach(x=>x.classList.toggle(\'active\',x===b));[\'deals\',\'alerts\',\'system\'].forEach(v=>{$(\'#\'+v+\'View\').hidden=(v!==b.dataset.view)});if(b.dataset.view===\'system\')renderSystem()});\ntry{const es=new EventSource(\'/api/events\');es.onmessage=async e=>{console.log(\'alert event\',e.data);await loadAll();if(\'Notification\'in window&&Notification.permission===\'granted\'){const a=JSON.parse(e.data);new Notification(\'Tairon Offerte\',{body:a.message})}}}catch(e){}\nloadAll();setInterval(loadAll,15000);\n</script></body></html>\n'

def now_iso(): return datetime.now(timezone.utc).isoformat()
def connect():
    con=sqlite3.connect(DB_PATH); con.row_factory=sqlite3.Row; return con

def init_db():
    con=connect()
    statements=[
      "CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,title TEXT NOT NULL,brand TEXT,source_type TEXT NOT NULL,retailer TEXT NOT NULL,region TEXT,unit TEXT,url TEXT,image_url TEXT)",
      "CREATE TABLE IF NOT EXISTS prices(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL,price REAL NOT NULL,original_price REAL,observed_at TEXT NOT NULL)",
      "CREATE TABLE IF NOT EXISTS alert_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,query TEXT NOT NULL,max_price REAL,source_type TEXT DEFAULT 'all',region TEXT,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL)",
      "CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL)",
      "CREATE TABLE IF NOT EXISTS alert_events(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,price REAL NOT NULL,discount_pct REAL NOT NULL,score INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(product_id,price,kind))"
    ]
    for s in statements: con.execute(s)
    defaults={'auto_enabled':'1','min_discount':'30','min_score':'75','scan_seconds':'900','source_filter':'all','region':'Lombardia'}
    for k,v in defaults.items(): con.execute("INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)",(k,v))
    con.commit(); con.close()

def cleanup_demo_rows():
    if DEMO_MODE: return
    ids=('amz-sony','amz-ssd','ess-rummo-lom','conad-rummo-cam','coop-caffe-ven','amz-oled','amz-airfryer')
    con=connect()
    marks=','.join('?' for _ in ids)
    con.execute(f"DELETE FROM prices WHERE product_id IN ({marks})",ids)
    con.execute(f"DELETE FROM alert_events WHERE product_id IN ({marks})",ids)
    con.execute(f"DELETE FROM products WHERE id IN ({marks})",ids)
    con.commit(); con.close()

def settings_dict(con): return {r['key']:r['value'] for r in con.execute("SELECT key,value FROM settings")}
def calc_metrics(history,current,original):
    hist=history[:] or ([original] if original else [current]); avg=mean(hist); min_hist=min(hist+[current]); baseline=max(avg,original or avg)
    discount=max(0,(baseline-current)/baseline*100) if baseline else 0; vs_avg=max(0,(avg-current)/avg*100) if avg else 0
    score=int(min(100,round(discount*.55+vs_avg*.75+(10 if current<=min_hist*1.03 else 0)+25)))
    return {'avg':round(avg,2),'min':round(min_hist,2),'discount_pct':round(discount,1),'vs_avg_pct':round(vs_avg,1),'score':score}

DEMO_MODE=os.getenv("DEMO_MODE","0").strip().lower() in ("1","true","yes","on")
AMAZON_CREDENTIAL_ID=os.getenv("AMAZON_CREDENTIAL_ID","").strip()
AMAZON_CREDENTIAL_SECRET=os.getenv("AMAZON_CREDENTIAL_SECRET","").strip()
AMAZON_CREDENTIAL_VERSION=os.getenv("AMAZON_CREDENTIAL_VERSION","3.2").strip() or "3.2"
AMAZON_PARTNER_TAG=os.getenv("AMAZON_PARTNER_TAG","").strip()
AMAZON_MARKETPLACE=os.getenv("AMAZON_MARKETPLACE","www.amazon.it").strip() or "www.amazon.it"
AMAZON_MIN_SAVING=int(os.getenv("AMAZON_MIN_SAVING","20") or 20)
AMAZON_DISCOVERY_TERMS=[x.strip() for x in os.getenv(
    "AMAZON_DISCOVERY_TERMS",
    "cuffie,ssd,smart tv,robot aspirapolvere,air fryer,lego,smartphone,power station"
).split(',') if x.strip()]
