def _plain_html(value):
    value=re.sub(r'<script\b.*?</script>', ' ', value or '', flags=re.I|re.S)
    value=re.sub(r'<style\b.*?</style>', ' ', value, flags=re.I|re.S)
    value=re.sub(r'<[^>]+>', ' ', value)
    return re.sub(r'\s+', ' ', html_lib.unescape(value)).strip()

def _price_value(text):
    m=re.search(r'(?:€\s*|EUR\s*)(\d{1,4}[,.]\d{2})',text or '',flags=re.I)
    return float(m.group(1).replace(',','.')) if m else None

def _looks_like_product(line):
    t=re.sub(r'\s+',' ',(line or '').strip())
    if len(t)<4 or len(t)>110: return False
    up=t.upper()
    bad=('SCONTO','FIDATY','PREZZI CORTI','AL KG','AL LITRO','AL PZ','OFFERTA','PROMOZION','TANTE ALTRE','ALIMENTARI','FRESCHI','CONFEZIONATI','VALIDO','DAL ','FINO AL','€','EUR')
    if any(x in up for x in bad): return False
    if re.fullmatch(r'[\d\s.,xX%+-]+',t): return False
    return sum(c.isalpha() for c in t)>=4

def _extract_offer_rows_from_pdf(pdf_bytes,pdf_url,validity=''):
    """Estrae singole offerte dai volantini Esselunga in modo tollerante ai layout PDF."""
    import hashlib
    rows=[]
    seen=set()
    total_markers=0

    def clean_line(s):
        s=(s or '').replace('\xa0',' ')
        return re.sub(r'\s+',' ',s).strip()

    def parse_price(s):
        if not s: return None
        s=s.replace('€','').replace('EUR','').strip()
        s=re.sub(r'[^\d,\.]','',s)
        if not s: return None
        if ',' in s:
            s=s.replace('.','').replace(',','.')
        try:
            v=float(s)
            return round(v,2) if 0.01<=v<=9999 else None
        except Exception:
            return None

    def find_prices(txt):
        vals=[]
        for pat in (
            r'€\s*(\d{1,4}[,.]\d{2})',
            r'(\d{1,4}[,.]\d{2})\s*€',
            r'\b(\d{1,3}[,.]\d{2})\b',
        ):
            for m in re.finditer(pat,txt,flags=re.I):
                v=parse_price(m.group(1))
                if v is not None and v not in vals:
                    vals.append(v)
        return vals

    def find_discount(txt):
        for pat in (
            r'SCONTO\s+FIDATY\s*-?\s*(\d{1,2})\s*%',
            r'SCONTO\s*-?\s*(\d{1,2})\s*%',
            r'-\s*(\d{1,2})\s*%',
            r'(\d{1,2})\s*%\s+DI\s+SCONTO',
        ):
            m=re.search(pat,txt,flags=re.I)
            if m:
                try:
                    pct=int(m.group(1))
                    if 1<=pct<=90: return pct
                except Exception:
                    pass
        return None

    def title_score(line):
        if not line: return -100
        up=line.upper()
        if any(x in up for x in ('SCONTO','FIDATY','PREZZO','OFFERTA','VALIDO','RISPARMIO','EURO','€')):
            return -20
        letters=len(re.findall(r'[A-Za-zÀ-ÿ]',line))
        digits=len(re.findall(r'\d',line))
        if letters<3: return -20
        score=letters + (10 if 5<=len(line)<=95 else 0)
        if digits>letters: score-=10
        return score

    try:
        reader=PdfReader(BytesIO(pdf_bytes))
    except Exception as e:
        print(f'[ESSELUNGA] errore apertura PDF: {e}')
        return []

    print(f'[ESSELUNGA] PDF aperto: {len(reader.pages)} pagine url={pdf_url}')

    for page_no,page in enumerate(reader.pages[:40],start=1):
        try:
            raw=page.extract_text() or ''
        except Exception as e:
            print(f'[ESSELUNGA] errore estrazione pagina={page_no}: {e}')
            continue
        if not raw.strip():
            continue

        lines=[clean_line(x) for x in raw.splitlines() if clean_line(x)]
        normalized='\n'.join(lines)
        markers=[]

        for pat in (
            r'SCONTO\s+FIDATY\s*-?\s*(\d{1,2})\s*%',
            r'SCONTO\s*-?\s*(\d{1,2})\s*%',
            r'-\s*(\d{1,2})\s*%',
            r'(\d{1,2})\s*%\s+DI\s+SCONTO',
        ):
            for m in re.finditer(pat,normalized,flags=re.I):
                try: pct=int(m.group(1))
                except Exception: continue
                if 1<=pct<=90:
                    markers.append((m.start(),m.end(),pct))

        # Fallback riga per riga per PDF con testo molto frammentato.
        if not markers:
            for idx,line in enumerate(lines):
                pct=find_discount(line)
                if pct:
                    markers.append(('line',idx,pct))

        total_markers+=len(markers)

        for marker in markers:
            if marker[0]=='line':
                idx=marker[1]; discount=marker[2]
                a=max(0,idx-8); b=min(len(lines),idx+9)
                win_lines=lines[a:b]
                win_text=' '.join(win_lines)
            else:
                a,b,discount=marker
                left=max(0,a-500); right=min(len(normalized),b+500)
                win_text=normalized[left:right]
                win_lines=[clean_line(x) for x in win_text.splitlines() if clean_line(x)]

            prices=find_prices(win_text)
            if not prices:
                continue

            title=None
            for cand in sorted(win_lines,key=title_score,reverse=True):
                if title_score(cand)>0:
                    title=cand
                    break
            if not title:
                continue

            title=clean_line(re.sub(r'€?\s*\d{1,4}[,.]\d{2}\s*€?','',title))
            if len(title)<3:
                continue

            offer=min(prices)
            original=max(prices) if len(prices)>=2 else None
            if original is not None and original<=offer:
                original=None

            # Se il vecchio prezzo non è leggibile, ricavalo dallo sconto dichiarato.
            if original is None and discount:
                try:
                    est=round(offer/(1-discount/100),2)
                    if est>offer: original=est
                except Exception:
                    pass
            elif original is not None:
                try:
                    calc=round(((original-offer)/original)*100)
                    if abs(calc-discount)>20:
                        est=round(offer/(1-discount/100),2)
                        if est>offer: original=est
                except Exception:
                    pass

            key=(title.lower(),offer,discount,page_no)
            if key in seen:
                continue
            seen.add(key)

            raw_id=f'{title}|{offer}|{discount}|{page_no}|{pdf_url}'
            oid='esselunga-'+hashlib.sha1(raw_id.encode('utf-8')).hexdigest()[:16]
            rows.append({
                'id':oid,
                'title':title.title() if title.isupper() else title,
                'retailer':'Esselunga',
                'region':ESSELUNGA_REGION,
                'price':round(offer,2),
                'original_price':round(original,2) if original else None,
                'discount_pct':discount,
                'validity':validity,
                'url':pdf_url,
                'page':page_no,
                'source_type':'market'
            })

    rows=sorted(rows,key=lambda z:(-z['discount_pct'],z['price']))
    print(f'[ESSELUNGA] marker_sconto={total_markers} offerte_estratte={len(rows)} url={pdf_url}')
    return rows[:80]

def _esselunga_headers():
    return {
        "User-Agent":"Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 Safari/604.1",
        "Accept-Language":"it-IT,it;q=0.9,en;q=0.5",
        "Accept":"text/html,application/xhtml+xml,application/json,text/plain,application/pdf;q=0.9,*/*;q=0.8",
    }


def _esselunga_get(url, timeout=6, attempts=3, headers=None):
    """GET con retry rapido per evitare che un timeout temporaneo azzeri tutta la scansione."""
    headers=headers or _esselunga_headers()
    last=None
    for attempt in range(1, attempts+1):
        try:
            r=requests.get(
                url,
                timeout=timeout,
                headers=headers,
                allow_redirects=True,
            )
            print(
                f"[ESSELUNGA] GET attempt={attempt}/{attempts} "
                f"status={r.status_code} bytes={len(r.content)} url={r.url}"
            )
            return r
        except Exception as e:
            last=e
            print(
                f"[ESSELUNGA] GET_RETRY attempt={attempt}/{attempts} "
                f"url={url} error={str(e)[:150]}"
            )
    if last:
        raise last
    raise RuntimeError("GET Esselunga fallito")


def _remember_esselunga_viewers(urls):
    global ESSELUNGA_VIEWER_CACHE
    for u in urls or []:
        if not u:
            continue
        if '/cdn/volantini/' not in u.lower():
            continue
        if u not in ESSELUNGA_VIEWER_CACHE:
            ESSELUNGA_VIEWER_CACHE.append(u)
    ESSELUNGA_VIEWER_CACHE=ESSELUNGA_VIEWER_CACHE[-20:]


def _cached_esselunga_targets():
    out=[]
    for u in ESSELUNGA_VIEWER_CACHE + ESSELUNGA_KNOWN_VIEWERS:
        if u and u not in out:
            out.append(u)
    return out


def _extract_offer_rows_from_text(raw_text, source_url, validity=''):
    """Estrae offerte Esselunga da testo HTML/JSON/JS del volantino digitale."""
    import hashlib

    def clean(s):
        s=html_lib.unescape(s or '')
        s=re.sub(r'<script\b.*?</script>',' ',s,flags=re.I|re.S)
        s=re.sub(r'<style\b.*?</style>',' ',s,flags=re.I|re.S)
        s=re.sub(r'<[^>]+>','\n',s)
        s=s.replace('\\/','/').replace('\\n','\n').replace('\\t',' ')
        s=re.sub(r'[\r\f\v]+','\n',s)
        s=re.sub(r'[ \t]+',' ',s)
        s=re.sub(r'\n{3,}','\n\n',s)
        return s

    def price_values(s):
        out=[]
        for pat in (
            r'€\s*(\d{1,4}[,.]\d{2})',
            r'(\d{1,4}[,.]\d{2})\s*€',
            r'\b(\d{1,3}[,.]\d{2})\b',
        ):
            for m in re.finditer(pat,s,flags=re.I):
                try:
                    v=float(m.group(1).replace('.','').replace(',','.')) if ',' in m.group(1) else float(m.group(1))
                    if 0.01<=v<=9999 and v not in out:
                        out.append(round(v,2))
                except Exception:
                    pass
        return out

    def find_discount(s):
        for pat in (
            r'SCONTO\s+FIDATY\s*-?\s*(\d{1,2})\s*%',
            r'SCONTO\s*-?\s*(\d{1,2})\s*%',
            r'-\s*(\d{1,2})\s*%',
            r'(\d{1,2})\s*%\s+(?:DI\s+)?SCONTO',
        ):
            m=re.search(pat,s,flags=re.I)
            if m:
                try:
                    p=int(m.group(1))
                    if 1<=p<=90:
                        return p
                except Exception:
                    pass
        return None

    def title_score(line):
        t=re.sub(r'\s+',' ',line or '').strip(' -·|')
        if len(t)<4 or len(t)>110:
            return -100
        up=t.upper()
        bad=(
            'SCONTO','FIDATY','OFFERTA','PREZZO','RISPARMIO','VALIDO',
            'DAL ','FINO AL','AL KG','AL LITRO','AL PZ','€','EUR',
            'VOLANTINO','ESSLUNGA','ESSELUNGA','COOKIE','PRIVACY'
        )
        if any(x in up for x in bad):
            return -50
        letters=sum(c.isalpha() for c in t)
        if letters<4:
            return -50
        return letters - sum(c.isdigit() for c in t)

    txt=clean(raw_text)
    lines=[re.sub(r'\s+',' ',x).strip() for x in txt.splitlines() if re.sub(r'\s+',' ',x).strip()]
    rows=[]
    seen=set()

    # Cerca marker di sconto in una finestra locale; funziona anche se l'HTML
    # separa titolo/prezzo/sconto su nodi diversi.
    for i,line in enumerate(lines):
        discount=find_discount(line)
        if not discount:
            continue

        a=max(0,i-12)
        b=min(len(lines),i+13)
        window=lines[a:b]
        joined=' '.join(window)
        prices=price_values(joined)
        if not prices:
            continue

        title_candidates=sorted(window,key=title_score,reverse=True)
        title=next((x for x in title_candidates if title_score(x)>0),None)
        if not title:
            continue

        title=re.sub(r'€?\s*\d{1,4}[,.]\d{2}\s*€?','',title)
        title=re.sub(r'\s+',' ',title).strip(' -·|')
        if len(title)<4:
            continue

        offer=min(prices)
        original=max(prices) if len(prices)>=2 else None
        if original is not None and original<=offer:
            original=None

        if original is None and discount:
            try:
                est=round(offer/(1-discount/100),2)
                if est>offer:
                    original=est
            except Exception:
                pass

        key=(title.lower(),offer,discount)
        if key in seen:
            continue
        seen.add(key)

        raw_id=f'{title}|{offer}|{discount}|{source_url}'
        rows.append({
            'id':'esselunga-'+hashlib.sha1(raw_id.encode('utf-8')).hexdigest()[:16],
            'title':title.title() if title.isupper() else title,
            'retailer':'Esselunga',
            'region':ESSELUNGA_REGION,
            'price':round(offer,2),
            'original_price':round(original,2) if original else None,
            'discount_pct':discount,
            'validity':validity,
            'url':source_url,
            'page':None,
            'source_type':'market'
        })

    print(f"[ESSELUNGA] TEXT_EXTRACT url={source_url} lines={len(lines)} offers={len(rows)}")
    return rows[:80]


def _discover_flipbook_urls(page_text, base_url):
    """Scopre asset interni del viewer: script, css, json, xml, html e data file."""
    urls=[]

    def add(v):
        if not v:
            return
        v=html_lib.unescape(v).replace('\\/','/').strip().strip('"\' ')
        if not v or v.startswith(('data:','javascript:','#')):
            return
        if v.startswith('//'):
            v='https:'+v
        try:
            u=urljoin(base_url,v)
        except Exception:
            return
        if u not in urls:
            urls.append(u)

    body=page_text or ''

    # HTML standard: script/link/img/source/iframe/a e attributi data-*.
    for m in re.finditer(
        r'(?:src|href|data-src|data-href|data-url|content)=["\']([^"\']+)["\']',
        body,flags=re.I
    ):
        add(m.group(1))

    # Stringhe JS/JSON contenenti asset o path relativi.
    for m in re.finditer(
        r'["\']([^"\']+\.(?:js|mjs|json|xml|txt|html?|css|jpg|jpeg|png|webp)(?:\?[^"\']*)?)["\']',
        body,flags=re.I
    ):
        add(m.group(1))

    # Path senza estensione ma tipicamente usati dai flipbook.
    for m in re.finditer(
        r'["\']([^"\']*(?:config|manifest|search|pages|pagefiles|javascript|data|content)[^"\']*)["\']',
        body,flags=re.I
    ):
        candidate=m.group(1)
        if len(candidate) < 220:
            add(candidate)

    return urls


def _flipbook_probe_urls(viewer_url):
    """Genera nomi comuni di config/data usati dai viewer statici."""
    base=viewer_url.rsplit('/',1)[0] + '/'
    names=[
        'config.js','settings.js','data.js','pages.js','manifest.json',
        'config.json','data.json','pages.json','bookConfig.json',
        'book_config.json','search.json','searchtext.js','search_config.js',
        'javascript/config.js','javascript/settings.js','javascript/data.js',
        'javascript/pages.js','javascript/search_config.js',
        'js/config.js','js/settings.js','js/data.js','js/pages.js',
        'js/search.js','data/config.json','data/pages.json','data/search.json',
        'search/searchtext.js','search/search_config.js','search/search.json',
        'files/assets/basic-html/page1.html','files/assets/search/searchtext.js',
    ]
    return [urljoin(base,n) for n in names]


def _extract_offer_rows_from_flipbook(viewer_url, validity=''):
    """Legge il viewer Esselunga seguendo davvero i suoi asset interni."""
    headers=_esselunga_headers()
    rows=[]
    visited=set()
    queue=[viewer_url]
    discovered_images=[]
    asset_hits=0

    # I primi probe vengono aggiunti subito, così non dipendiamo dai nomi
    # presenti nell'index.html.
    for u in _flipbook_probe_urls(viewer_url):
        if u not in queue:
            queue.append(u)

    while queue and len(visited)<40:
        u=queue.pop(0)
        if u in visited:
            continue
        visited.add(u)

        try:
            r=_esselunga_get(u,timeout=5,attempts=1,headers=headers)
        except Exception as e:
            print(f"[ESSELUNGA] ASSET_FETCH_ERROR url={u} error={str(e)[:140]}")
            continue

        if not r.ok:
            continue

        ctype=(r.headers.get('content-type') or '').lower()
        final=r.url or u

        print(
            f"[ESSELUNGA] ASSET_FETCH status={r.status_code} "
            f"type={ctype[:55]} bytes={len(r.content)} url={final}"
        )

        if 'application/pdf' in ctype or r.content[:4]==b'%PDF':
            try:
                got=_extract_offer_rows_from_pdf(r.content,final,validity)
                if got:
                    print(f"[ESSELUNGA] ASSET_PDF_OFFERS count={len(got)}")
                    return got
            except Exception as e:
                print(f"[ESSELUNGA] ASSET_PDF_ERROR {str(e)[:140]}")
            continue

        is_text=(
            any(x in ctype for x in ('text/','json','javascript','xml'))
            or final.lower().split('?',1)[0].endswith(
                ('.js','.mjs','.json','.xml','.txt','.html','.htm','.css')
            )
        )
        if not is_text:
            if final.lower().split('?',1)[0].endswith(('.jpg','.jpeg','.png','.webp')):
                if final not in discovered_images:
                    discovered_images.append(final)
            continue

        try:
            body=r.text or ''
        except Exception:
            continue

        asset_hits+=1

        got=_extract_offer_rows_from_text(body,final,validity)
        if got:
            rows.extend(got)
            print(
                f"[ESSELUNGA] ASSET_TEXT_OFFERS url={final} "
                f"count={len(got)} total={len(rows)}"
            )
            if len(rows)>=30:
                break

        # Segui tutti gli asset plausibili scoperti dentro questo file.
        for child in _discover_flipbook_urls(body,final):
            lc=child.lower().split('?',1)[0]

            if lc.endswith(('.jpg','.jpeg','.png','.webp')):
                if child not in discovered_images:
                    discovered_images.append(child)
                continue

            if (
                lc.endswith(('.js','.mjs','.json','.xml','.txt','.html','.htm','.css'))
                or any(k in lc for k in (
                    '/javascript/','/js/','/data/','/search/','/pages/',
                    'config','manifest','content','pagefiles'
                ))
            ):
                if child not in visited and child not in queue and len(queue)<100:
                    queue.append(child)

        # Alcuni viewer costruiscono URL senza virgolette in JS.
        for m in re.finditer(
            r'(?:(?:url|src|file|path|config|manifest|search)[\s:=]+)'
            r'["\']?([^"\'\s,;})]+\.(?:js|json|xml|txt|html?))',
            body,flags=re.I
        ):
            child=urljoin(final,m.group(1).replace('\\/','/'))
            if child not in visited and child not in queue:
                queue.append(child)

    out=[]
    keys=set()
    for x in rows:
        k=(x['title'].lower(),x['price'],x['discount_pct'])
        if k in keys:
            continue
        keys.add(k)
        out.append(x)

    print(
        f"[ESSELUNGA] FLIP_DONE viewer={viewer_url} "
        f"visited={len(visited)} text_assets={asset_hits} "
        f"images_seen={len(discovered_images)} offers={len(out)}"
    )

    # Log utile per il prossimo passo se il viewer fosse puramente immagine.
    if not out and discovered_images:
        print(
            f"[ESSELUNGA] IMAGE_ONLY_FALLBACK images={len(discovered_images)} "
            f"sample={discovered_images[:5]}"
        )

    return out[:80]

def _extract_esselunga_target(target_url, validity=''):
    """Prova PDF, HTML digitale e flipbook CDN, in quest'ordine."""
    headers=_esselunga_headers()
    try:
        r=_esselunga_get(target_url,timeout=5,attempts=2,headers=headers)
    except Exception as e:
        print(f"[ESSELUNGA] TARGET_FETCH_ERROR url={target_url} error={str(e)[:160]}")
        return [],None

    ctype=(r.headers.get('content-type') or '').lower()
    final_url=r.url or target_url
    print(
        f"[ESSELUNGA] TARGET status={r.status_code} type={ctype[:65]} "
        f"bytes={len(r.content)} url={final_url}"
    )
    if not r.ok:
        return [],None

    if 'application/pdf' in ctype or r.content[:4]==b'%PDF':
        try:
            return _extract_offer_rows_from_pdf(r.content,final_url,validity),'pdf'
        except Exception as e:
            print(f"[ESSELUNGA] TARGET_PDF_ERROR {str(e)[:160]}")
            return [],'pdf'

    body=r.text or ''

    # 1) Le pagine "volantino-digitale" Esselunga spesso contengono già
    # testo/JSON utile nel markup.
    direct=_extract_offer_rows_from_text(body,final_url,validity)
    if direct:
        return direct,'html'

    # 2) Cerca il viewer CDN del flipbook.
    viewers=[
        u for u in _discover_flipbook_urls(body,final_url)
        if '/cdn/volantini/' in u.lower() or u.lower().endswith('/index.html')
    ]
    _remember_esselunga_viewers(viewers)
    print(f"[ESSELUNGA] VIEWERS count={len(viewers)} target={final_url}")

    for viewer in viewers[:3]:
        got=_extract_offer_rows_from_flipbook(viewer,validity)
        if got:
            return got,'flipbook'

    # Se il target stesso è già il viewer CDN.
    if '/cdn/volantini/' in final_url.lower():
        got=_extract_offer_rows_from_flipbook(final_url,validity)
        if got:
            return got,'flipbook'

    return [],'html'


def fetch_esselunga_promotions():
    """Legge campagne/offerte Esselunga con retry e fallback diretto al CDN."""
    global SUPERMARKET_PROMOTIONS,SUPERMARKET_OFFERS,ESSELUNGA_PROMO_CACHE
    headers=_esselunga_headers()
    print(
        f"[ESSELUNGA] START page={ESSELUNGA_PAGE} "
        f"store={ESSELUNGA_STORE_CODE} region={ESSELUNGA_REGION}"
    )

    page=None
    landing_url=ESSELUNGA_PAGE
    landing_error=None

    try:
        r=_esselunga_get(ESSELUNGA_PAGE,timeout=5,attempts=3,headers=headers)
        r.raise_for_status()
        page=r.text or ''
        landing_url=r.url or ESSELUNGA_PAGE
        print(
            f"[ESSELUNGA] LANDING_OK final_url={landing_url} "
            f"bytes={len(r.content)}"
        )
    except Exception as e:
        landing_error=str(e)[:220]
        print(f"[ESSELUNGA] LANDING_FAIL error={landing_error}")

    found=[]

    if page:
        matches=list(re.finditer(r'<h3[^>]*>(.*?)</h3>',page,flags=re.I|re.S))
        print(f"[ESSELUNGA] H3_FOUND count={len(matches)}")

        for i,m in enumerate(matches):
            title=_plain_html(m.group(1))
            if not title or 'PROMOZIONI' in title.upper() or title.lower().startswith('seleziona un negozio'):
                continue

            end=matches[i+1].start() if i+1<len(matches) else min(len(page),m.end()+8000)
            chunk=page[m.end():end]
            txt=_plain_html(chunk)

            dm=re.search(
                r'((?:Dal|Fino al)\s+.{3,120}?)(?=(?:Sfoglia|Scopri|Altri|Novit|Ultimo|In arrivo|$))',
                txt,flags=re.I
            )
            validity=re.sub(r'\s+',' ',dm.group(1)).strip(' ·-') if dm else ''

            hrefs=[
                urljoin(landing_url,html_lib.unescape(h).replace('\\/','/'))
                for h in re.findall(
                    r'(?:href|src|data-href|data-src|data-url)=["\']([^"\']+)["\']',
                    chunk,flags=re.I
                )
            ]

            digital=next((h for h in hrefs if 'volantino-digitale' in h.lower()),None)
            flyer=next((h for h in hrefs if 'volantino.' in h.lower() or '/cdn/volantini/' in h.lower()),None)
            discover=next(
                (h for h in hrefs if any(k in h.lower() for k in ('offerte','promo','flyer','leaflet'))),
                None
            )
            href=digital or flyer or discover or (hrefs[0] if hrefs else landing_url)

            viewers=[
                u for u in hrefs
                if '/cdn/volantini/' in u.lower()
            ]
            _remember_esselunga_viewers(viewers)

            found.append({
                'id':f"esselunga-{ESSELUNGA_STORE_CODE}-{len(found)+1}",
                'title':title,
                'retailer':'Esselunga',
                'region':ESSELUNGA_REGION,
                'validity':validity,
                'url':href,
                'flyer_url':flyer,
                'offers_url':digital or discover,
                'store_code':ESSELUNGA_STORE_CODE
            })

    # Se landing è riuscita, aggiorna la cache delle campagne.
    if found:
        seen=set()
        out=[]
        for x in found:
            k=(x['title'].lower(),x['validity'].lower(),x.get('url',''))
            if k in seen:
                continue
            seen.add(k)
            out.append(x)
        SUPERMARKET_PROMOTIONS=out[:30]
        ESSELUNGA_PROMO_CACHE=[dict(x) for x in SUPERMARKET_PROMOTIONS]
        print(f"[ESSELUNGA] CAMPAIGNS count={len(SUPERMARKET_PROMOTIONS)} source=landing")

    # Se la landing è KO, conserva/promuove la cache in memoria anziché azzerare tutto.
    elif ESSELUNGA_PROMO_CACHE:
        SUPERMARKET_PROMOTIONS=[dict(x) for x in ESSELUNGA_PROMO_CACHE]
        print(
            f"[ESSELUNGA] CAMPAIGNS count={len(SUPERMARKET_PROMOTIONS)} "
            f"source=memory_cache"
        )
    else:
        SUPERMARKET_PROMOTIONS=[]

    offers=[]
    sources_ok=0

    # 1) Prova le campagne normali/cache.
    for idx,promo in enumerate(SUPERMARKET_PROMOTIONS[:5],start=1):
        targets=[]
        for candidate in (
            promo.get('offers_url'),
            promo.get('flyer_url'),
            promo.get('url'),
        ):
            if candidate and candidate not in targets:
                targets.append(candidate)

        print(
            f"[ESSELUNGA] CAMPAIGN index={idx} title={promo.get('title','')[:80]} "
            f"targets={len(targets)}"
        )

        campaign_rows=[]
        source_kind=None
        for target in targets[:2]:
            got,kind=_extract_esselunga_target(target,promo.get('validity',''))
            if got:
                campaign_rows=got
                source_kind=kind
                break

        if campaign_rows:
            sources_ok+=1
            promo['offer_source']=source_kind
            promo['offers_count']=len(campaign_rows)
            offers.extend(campaign_rows)
            print(
                f"[ESSELUNGA] CAMPAIGN_DONE index={idx} "
                f"source={source_kind} offers={len(campaign_rows)}"
            )
        else:
            promo['extract_error']='Nessuna offerta testuale trovata'
            print(f"[ESSELUNGA] CAMPAIGN_EMPTY index={idx}")

    # 2) Fallback diretto CDN. Parte anche se www.esselunga.it è completamente irraggiungibile.
    if not offers:
        cached_targets=_cached_esselunga_targets()
        print(f"[ESSELUNGA] CDN_FALLBACK targets={len(cached_targets)}")
        for viewer in cached_targets[:6]:
            try:
                got=_extract_offer_rows_from_flipbook(viewer,'')
            except Exception as e:
                print(
                    f"[ESSELUNGA] CDN_FALLBACK_ERROR "
                    f"url={viewer} error={str(e)[:150]}"
                )
                continue
            if got:
                offers.extend(got)
                sources_ok+=1
                print(
                    f"[ESSELUNGA] CDN_FALLBACK_OK "
                    f"url={viewer} offers={len(got)}"
                )
                if len(offers)>=30:
                    break

    dedup=[]
    keys=set()
    for x in offers:
        k=(x['title'].lower(),x['price'],x['discount_pct'])
        if k in keys:
            continue
        keys.add(k)
        dedup.append(x)

    # Non cancellare offerte valide già lette in precedenza per un timeout temporaneo.
    if dedup:
        SUPERMARKET_OFFERS=dedup[:80]
    elif SUPERMARKET_OFFERS:
        print(
            f"[ESSELUNGA] KEEP_PREVIOUS_OFFERS count={len(SUPERMARKET_OFFERS)} "
            f"landing_error={bool(landing_error)}"
        )
    else:
        SUPERMARKET_OFFERS=[]

    if not SUPERMARKET_PROMOTIONS and ESSELUNGA_PROMO_CACHE:
        SUPERMARKET_PROMOTIONS=[dict(x) for x in ESSELUNGA_PROMO_CACHE]

    err=None
    if not SUPERMARKET_OFFERS:
        err=landing_error or "Volantini raggiunti ma nessuna offerta testuale estratta"

    SOURCE_STATE['supermarkets'].update(
        configured=True,
        live=bool(SUPERMARKET_OFFERS or SUPERMARKET_PROMOTIONS),
        last_ok=now_iso() if (SUPERMARKET_OFFERS or SUPERMARKET_PROMOTIONS) else SOURCE_STATE['supermarkets'].get('last_ok'),
        last_error=err,
        items=len(SUPERMARKET_OFFERS),
        campaigns=len(SUPERMARKET_PROMOTIONS),
        offer_sources=sources_ok,
        cdn_cache=len(ESSELUNGA_VIEWER_CACHE),
    )

    print(
        f"[ESSELUNGA] DONE campaigns={len(SUPERMARKET_PROMOTIONS)} "
        f"sources_ok={sources_ok} offers={len(SUPERMARKET_OFFERS)} "
        f"cdn_cache={len(ESSELUNGA_VIEWER_CACHE)} "
        f"landing_ok={page is not None}"
    )
    return SUPERMARKET_PROMOTIONS

def _amazon_token_endpoint():
    # Credential version 3.2 is the EU token flow documented for IT.
    if AMAZON_CREDENTIAL_VERSION.startswith("3.1"):
        return "https://api.amazon.com/auth/o2/token"
    if AMAZON_CREDENTIAL_VERSION.startswith("3.3"):
        return "https://api.amazon.co.jp/auth/o2/token"
    return "https://api.amazon.co.uk/auth/o2/token"

def _amazon_access_token():
    r=requests.post(_amazon_token_endpoint(),json={
        "grant_type":"client_credentials",
        "client_id":AMAZON_CREDENTIAL_ID,
        "client_secret":AMAZON_CREDENTIAL_SECRET,
        "scope":"creatorsapi::default"
    },timeout=20,headers={"Content-Type":"application/json","User-Agent":"Tairon-Offerte/1.1"})
    r.raise_for_status()
    data=r.json()
    token=data.get("access_token")
    if not token: raise RuntimeError("Amazon OAuth: access_token mancante")
    return token

def _amazon_terms(con):
    terms=list(AMAZON_DISCOVERY_TERMS)
    try:
        for r in con.execute("SELECT query FROM alert_rules WHERE enabled=1 AND source_type IN ('all','online') ORDER BY id DESC LIMIT 20"):
            q=(r['query'] or '').strip()
            if q and q.lower() not in {x.lower() for x in terms}: terms.append(q)
    except Exception: pass
    return terms[:24]

def fetch_amazon_deals(terms):
    """Legge offerte reali da Amazon Creators API per termini discovery/watchlist.
    Nota: Creators API non è un feed globale di tutte le offerte; questa beta scandaglia termini e watchlist.
    """
    if not AMAZON_CONFIGURED:
        SOURCE_STATE["amazon"].update(configured=False,live=False,last_error="Credenziali Creators API non configurate",items=0)
        return []
    try:
        token=_amazon_access_token()
        headers={
            "Authorization":f"Bearer {token}",
            "Content-Type":"application/json",
            "x-marketplace":AMAZON_MARKETPLACE,
            "User-Agent":"Tairon-Offerte/1.1"
        }
        found={}
        for term in terms:
            payload={
                "partnerTag":AMAZON_PARTNER_TAG,
                "marketplace":AMAZON_MARKETPLACE,
                "keywords":term,
                "searchIndex":"All",
                "itemCount":10,
                "minSavingPercent":max(1,min(99,AMAZON_MIN_SAVING)),
                "resources":[
                    "images.primary.medium","itemInfo.title",
                    "offersV2.listings.price","offersV2.listings.dealDetails","offersV2.listings.type"
                ]
            }
            r=requests.post("https://creatorsapi.amazon/catalog/v1/searchItems",json=payload,headers=headers,timeout=25)
            r.raise_for_status()
            data=r.json()
            for item in ((data.get("searchResult") or {}).get("items") or []):
                asin=(item.get("asin") or '').strip()
                title=html_lib.unescape((((item.get("itemInfo") or {}).get("title") or {}).get("displayValue") or '').strip())
                if not asin or not title: continue
                listings=((item.get("offersV2") or {}).get("listings") or [])
                if not listings: continue
                # Prefer buy-box/deal listing when present.
                listing=next((x for x in listings if x.get("isBuyBoxWinner")), listings[0])
                price=(listing.get("price") or {})
                money=(price.get("money") or {})
                amount=money.get("amount")
                if amount is None: continue
                amount=float(amount)
                basis=((price.get("savingBasis") or {}).get("money") or {}).get("amount")
                savings=(price.get("savings") or {}).get("percentage")
                baseline=float(basis) if basis is not None else amount
                if baseline<=0: baseline=amount
                drop=float(savings) if savings is not None else (max(0,(baseline-amount)/baseline*100) if baseline else 0)
                img=((((item.get("images") or {}).get("primary") or {}).get("medium") or {}).get("url"))
                url=(item.get("detailPageURL") or f"https://www.amazon.it/dp/{asin}")
                found[asin]={
                    "id":f"amazon-{asin}","asin":asin,"title":title,"brand":"",
                    "source_type":"online","retailer":"Amazon","region":None,"unit":"pz",
                    "base":round(baseline,2),"offer":round(amount,2),"url":url,
                    "image_url":img,"live_source":"amazon","reported_saving":round(drop,1),
                    "deal_type":listing.get("type") or ((listing.get("dealDetails") or {}).get("accessType"))
                }
        out=list(found.values())
        SOURCE_STATE["amazon"].update(configured=True,live=True,last_ok=now_iso(),last_error=None,items=len(out))
        return out
    except Exception as e:
        SOURCE_STATE["amazon"].update(configured=True,live=False,last_error=str(e)[:240],items=0)
        print("amazon creators error",e)
        return []

