def emit(con,p,m,kind,suffix=''):
    msg=f"{p['retailer']}: {p['title']} a {p['price']:.2f} € · -{m['discount_pct']:.0f}% · Score {m['score']}{suffix}"
    try: con.execute("INSERT INTO alert_events(product_id,kind,title,message,price,discount_pct,score,created_at) VALUES(?,?,?,?,?,?,?,?)",(p['id'],kind,p['title'],msg,p['price'],m['discount_pct'],m['score'],now_iso()))
    except sqlite3.IntegrityError: pass

def watch_matches(con,p):
    for r in con.execute("SELECT * FROM alert_rules WHERE enabled=1"):
        if r['query'].lower() not in p['title'].lower(): continue
        if r['source_type']!='all' and r['source_type']!=p['source_type']: continue
        if r['region'] and p['source_type']=='market' and r['region']!=p['region']: continue
        if r['max_price'] is not None and p['price']>r['max_price']: continue
        return True
    return False

async def scan_once():
    con=connect(); st=settings_dict(con); n=0
    terms=_amazon_terms(con)
    real_rows=await asyncio.to_thread(fetch_amazon_deals,terms)
    await asyncio.to_thread(fetch_esselunga_promotions)
    rows=list(real_rows)
    if DEMO_MODE:
        for d in DEMO:
            rows.append({**d,'price':round(d['offer']*(1+random.uniform(-0.01,0.01)),2),'live_source':'demo'})
        SOURCE_STATE['demo'].update(last_ok=now_iso(),items=len(DEMO))
    for d in rows:
        price=float(d.get('price',d.get('offer',0)) or 0)
        if price<=0: continue
        p={**d,'price':price}
        con.execute("INSERT INTO products(id,title,brand,source_type,retailer,region,unit,url,image_url) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,brand=excluded.brand,source_type=excluded.source_type,retailer=excluded.retailer,region=excluded.region,unit=excluded.unit,url=excluded.url,image_url=excluded.image_url",(p['id'],p['title'],p.get('brand'),p['source_type'],p['retailer'],p.get('region'),p.get('unit'),p.get('url'),p.get('image_url')))
        hist=[float(r['price']) for r in con.execute("SELECT price FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 180",(p['id'],))]
        baseline=float(d.get('base') or price)
        # Local history becomes increasingly important over time; first observation can use Amazon saving basis.
        m=calc_metrics(hist,price,baseline)
        if p['id'].startswith('amazon-') and not hist and baseline>0:
            m['avg']=round(baseline,2)
            m['discount_pct']=round(max(0,(baseline-price)/baseline*100),1)
            m['vs_avg_pct']=m['discount_pct']
            m['score']=int(min(100,round(m['discount_pct']*1.35+20)))
        con.execute("INSERT INTO prices(product_id,price,original_price,observed_at) VALUES(?,?,?,?)",(p['id'],price,baseline,now_iso()))
        ok_source=st.get('source_filter','all') in ('all',p['source_type']); ok_region=p['source_type']!='market' or p.get('region')==st.get('region','Lombardia')
        live=p['id'].startswith('amazon-')
        if st.get('auto_enabled','1')=='1' and ok_source and ok_region and m['discount_pct']>=float(st.get('min_discount','30')) and m['score']>=int(st.get('min_score','75')): emit(con,p,m,'auto',' · LIVE Amazon' if live else ' · DEMO')
        if watch_matches(con,p): emit(con,p,m,'watchlist',' · LIVE Amazon watchlist' if live else ' · demo watchlist')
        n+=1
    con.commit(); con.close(); return n

stop_event=asyncio.Event(); scanner_task=None
async def scanner_loop():
    while not stop_event.is_set():
        try: await scan_once()
        except Exception as e: print('scan error',e)
        con=connect(); seconds=int(settings_dict(con).get('scan_seconds','30')); con.close()
        try: await asyncio.wait_for(stop_event.wait(),timeout=seconds)
        except asyncio.TimeoutError: pass

@asynccontextmanager
async def lifespan(app:FastAPI):
    global scanner_task
    # FIX 1.3.4:
    # il server deve diventare disponibile subito. La scansione Esselunga può
    # richiedere decine di secondi e non deve bloccare lo startup di Uvicorn.
    init_db()
    cleanup_demo_rows()

    stop_event.clear()
    scanner_task = asyncio.create_task(scanner_loop())

    print('[STARTUP] API_READY scanner_started_in_background=true')
    yield

    stop_event.set()
    if scanner_task:
        try:
            await asyncio.wait_for(scanner_task, timeout=5)
        except asyncio.TimeoutError:
            scanner_task.cancel()
        except asyncio.CancelledError:
            pass

