@app.get('/api/deals')
def deals(region:str|None=None,source:str='all'):
    con=connect(); result=[]
    for p in con.execute("SELECT * FROM products ORDER BY retailer,title").fetchall():
        if source!='all' and p['source_type']!=source: continue
        if p['source_type']=='market' and region and p['region']!=region: continue
        latest=con.execute("SELECT * FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 1",(p['id'],)).fetchone(); hist=[float(r['price']) for r in con.execute("SELECT price FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 40",(p['id'],))]
        if latest: result.append({**dict(p),'price':latest['price'],'original_price':latest['original_price'],**calc_metrics(hist[1:],float(latest['price']),latest['original_price'])})
    con.close(); return result
@app.get('/api/watchlist')
def watchlist():
    con=connect(); rows=[dict(r) for r in con.execute("SELECT * FROM alert_rules ORDER BY id DESC")]; con.close(); return rows
@app.post('/api/watchlist')
def add_watchlist(r:AlertRuleIn):
    con=connect(); cur=con.execute("INSERT INTO alert_rules(query,max_price,source_type,region,enabled,created_at) VALUES(?,?,?,?,?,?)",(r.query,r.max_price,r.source_type,r.region,1 if r.enabled else 0,now_iso())); con.commit(); rid=cur.lastrowid; con.close(); return {'ok':True,'id':rid}
@app.delete('/api/watchlist/{rule_id}')
def del_watchlist(rule_id:int):
    con=connect(); cur=con.execute("DELETE FROM alert_rules WHERE id=?",(rule_id,)); con.commit(); found=cur.rowcount; con.close();
    if not found: raise HTTPException(404,'Rule not found')
    return {'ok':True}
@app.get('/api/alerts')
def alerts(limit:int=Query(50,ge=1,le=200),after:int=0):
    con=connect(); rows=[dict(r) for r in con.execute("SELECT * FROM alert_events WHERE id>? ORDER BY id DESC LIMIT ?",(after,limit))]; con.close(); return rows
@app.post('/api/scan/now')
async def scan_now(): return {'ok':True,'scanned':await scan_once(),'time':now_iso()}
@app.get('/api/events')
async def events():
    async def stream():
        last=0
        while True:
            con=connect(); rows=con.execute("SELECT * FROM alert_events WHERE id>? ORDER BY id",(last,)).fetchall(); con.close()
            for r in rows:
                last=r['id']; yield f"data: {json.dumps(dict(r),ensure_ascii=False)}\n\n"
            yield ': ping\n\n'; await asyncio.sleep(3)
    return StreamingResponse(stream(),media_type='text/event-stream')

